export const MOONS=[{"id": "phobos", "n": "Phobos", "k": "Moon of Mars", "at": "mars", "r": 0.9, "off": [20, 2, 4], "tex": "nasa", "facts": ["Phobos is only about 22 km across.", "It is slowly spiralling toward Mars and will break apart or crash in tens of millions of years.", "It rises in the west and sets in the east, twice a Martian day."]}, {"id": "deimos", "n": "Deimos", "k": "Moon of Mars", "at": "mars", "r": 0.6, "off": [-18, -3, 22], "tex": "nasa", "facts": ["Deimos is about 12 km across, one of the smallest moons known.", "Its surface is smooth, covered in a thick layer of dust.", "From Mars it looks like a bright star."]}, {"id": "io", "n": "Io", "k": "Moon of Jupiter", "at": "jupiter", "r": 3.6, "off": [52, 4, 10], "tex": "nasa", "facts": ["Io is the most volcanically active world in the solar system, with hundreds of volcanoes.", "Jupiter’s gravity squeezes Io, heating its insides.", "Some volcanoes shoot lava fountains many kilometres high."]}, {"id": "europa", "n": "Europa", "k": "Moon of Jupiter", "at": "jupiter", "r": 3.1, "off": [-40, -5, 48], "tex": "nasa", "facts": ["Under Europa’s ice shell is a salty ocean with more water than all of Earth’s oceans.", "NASA’s Europa Clipper launched in October 2024 to study it.", "Its surface is covered in long cracks and ridges."]}, {"id": "ganymede", "n": "Ganymede", "k": "Moon of Jupiter", "at": "jupiter", "r": 5.2, "off": [20, 8, -74], "tex": "nasa", "facts": ["Ganymede is the largest moon in the solar system, bigger than the planet Mercury.", "It is the only moon known to have its own magnetic field.", "Scientists think it also hides an ocean under its ice."]}, {"id": "callisto", "n": "Callisto", "k": "Moon of Jupiter", "at": "jupiter", "r": 4.8, "off": [-88, -6, -30], "tex": "nasa", "facts": ["Callisto is one of the most heavily cratered worlds in the solar system.", "Its surface is about 4 billion years old.", "It orbits far enough from Jupiter to escape most of its harsh radiation."]}, {"id": "mimas", "n": "Mimas", "k": "Moon of Saturn", "at": "saturn", "r": 1, "off": [84, 3, 8], "tex": "nasa", "facts": ["Mimas has a giant crater, Herschel, almost a third as wide as the moon itself.", "That crater makes it look a lot like a famous movie space station.", "It is the smallest round moon of Saturn."]}, {"id": "enceladus", "n": "Enceladus", "k": "Moon of Saturn", "at": "saturn", "r": 1.2, "off": [-60, 4, 68], "tex": "nasa", "facts": ["Enceladus shoots geysers of water ice from cracks at its south pole.", "Those geysers feed Saturn’s E ring.", "Cassini flew through the spray and found salt and organic molecules."]}, {"id": "tethys", "n": "Tethys", "k": "Moon of Saturn", "at": "saturn", "r": 1.6, "off": [30, -6, -96], "tex": "nasa", "facts": ["Tethys has a giant crater called Odysseus.", "A canyon, Ithaca Chasma, wraps around three-quarters of the moon.", "It is made almost entirely of water ice."]}, {"id": "dione", "n": "Dione", "k": "Moon of Saturn", "at": "saturn", "r": 1.7, "off": [-108, 6, -20], "tex": "nasa", "facts": ["Dione has bright ice cliffs that look like wispy streaks.", "It may have an ocean deep under its surface.", "Two tiny moons share its orbit."]}, {"id": "rhea", "n": "Rhea", "k": "Moon of Saturn", "at": "saturn", "r": 2.2, "off": [96, -8, -78], "tex": "nasa", "facts": ["Rhea is Saturn’s second-largest moon.", "It is a ball of ice and rock about 1,500 km across.", "Cassini found a very thin oxygen atmosphere around it."]}, {"id": "titan", "n": "Titan", "k": "Moon of Saturn", "at": "saturn", "r": 5.1, "off": [-140, 10, 40], "tex": "nasa", "facts": ["Titan is the only moon with a thick atmosphere.", "It has lakes and seas of liquid methane and ethane.", "The Huygens probe landed on Titan on 14 January 2005, and NASA’s Dragonfly drone will fly there."]}, {"id": "iapetus", "n": "Iapetus", "k": "Moon of Saturn", "at": "saturn", "r": 2.1, "off": [150, 14, 110], "tex": "nasa", "facts": ["Iapetus is two-toned: one side is dark, the other bright.", "A giant ridge runs around its middle like a walnut seam.", "It orbits far from Saturn, taking 79 days per trip."]}, {"id": "miranda", "n": "Miranda", "k": "Moon of Uranus", "at": "uranus", "r": 1, "off": [30, 2, 6], "tex": "nasa", "facts": ["Miranda looks like a patchwork of different terrains stuck together.", "Its cliff Verona Rupes may be the tallest cliff in the solar system.", "Voyager 2 photographed it in 1986."]}, {"id": "ariel", "n": "Ariel", "k": "Moon of Uranus", "at": "uranus", "r": 1.7, "off": [-26, -3, 30], "tex": "nasa", "facts": ["Ariel has the brightest surface of Uranus’s big moons.", "Long canyons cross its surface.", "Uranus’s moons are named after characters from Shakespeare and Alexander Pope."]}, {"id": "umbriel", "n": "Umbriel", "k": "Moon of Uranus", "at": "uranus", "r": 1.7, "off": [10, 4, -44], "tex": "nasa", "facts": ["Umbriel is the darkest of Uranus’s large moons.", "It has a bright ring at the top of one crater, nicknamed the “fluorescent Cheerio”.", "It is old and heavily cratered."]}, {"id": "titania", "n": "Titania", "k": "Moon of Uranus", "at": "uranus", "r": 2.2, "off": [-48, -5, -18], "tex": "nasa", "facts": ["Titania is the largest moon of Uranus.", "It is named after the queen of the fairies in Shakespeare’s “A Midsummer Night’s Dream”.", "Huge canyons on it suggest it once stretched as its inside froze."]}, {"id": "oberon", "n": "Oberon", "k": "Moon of Uranus", "at": "uranus", "r": 2.1, "off": [52, 6, -30], "tex": "nasa", "facts": ["Oberon is the outermost large moon of Uranus.", "It is named after the fairy king in “A Midsummer Night’s Dream”.", "It has a mountain about 11 km tall."]}, {"id": "triton", "n": "Triton", "k": "Moon of Neptune", "at": "neptune", "r": 2.7, "off": [30, 3, 8], "tex": "nasa", "facts": ["Triton orbits Neptune backwards, so it was probably captured from the Kuiper Belt.", "Voyager 2 saw geysers of nitrogen gas on Triton in 1989.", "It is one of the coldest places ever measured, about −235 °C."]}, {"id": "charon", "n": "Charon", "k": "Moon of Pluto", "at": "pluto", "r": 1.3, "off": [10, 1, 4], "tex": "nasa", "facts": ["Charon is about half as wide as Pluto.", "Pluto and Charon circle a point between them, like a spinning dumbbell.", "Its north pole is stained red, nicknamed Mordor Macula."]}];
