export const SAMPLE_FACTS={"earth": ["Kennedy Space Center has launched Apollo, the Space Shuttle and Artemis.", "The Vehicle Assembly Building’s doors are the tallest in the world.", "Florida is used for launches partly because rockets get a speed boost from Earth’s spin near the equator."], "moon": ["Footprints on the Moon can last millions of years because there is no wind.", "Apollo astronauts brought back 382 kg of Moon rocks.", "Moon dust is sharp, like tiny pieces of broken glass."], "mars": ["Mars is red because its dust contains rusty iron.", "Jezero Crater once held a lake, fed by a river delta.", "Sunsets on Mars look blue."], "mercury": ["Mercury has ice in craters at its poles that never see sunlight.", "Its Caloris Basin is about 1,550 km wide."], "venus": ["Venus’s clouds are made of sulfuric acid droplets.", "Soviet Venera landers survived on the surface for up to about two hours."], "ceres": ["Dawn found bright patches of salt in Occator Crater.", "Ceres may have had liquid water underground."], "pluto": ["Pluto’s heart-shaped plain, Sputnik Planitia, is made of frozen nitrogen.", "New Horizons flew past Pluto on 14 July 2015.", "Pluto has mountains of water ice as tall as the Rockies."]};

export const NEWOBJ=[{"id": "curiosity", "n": "Curiosity Rover", "k": "Mars rover", "ag": "NASA", "yr": 2011, "z": "mars-site", "facts": ["Curiosity landed in Gale Crater on 6 August 2012 (UTC), lowered by a rocket-powered “sky crane”.", "It found that Gale Crater once held a lake that could have supported tiny life.", "It is about the size of a small car and runs on nuclear power."]}, {"id": "spirit", "n": "Spirit Rover", "k": "Mars rover (ended)", "ag": "NASA", "yr": 2003, "z": "mars-site", "model": "opportunity", "facts": ["Spirit, Opportunity’s twin, landed in Gusev Crater on 4 January 2004.", "It found silica deposits that point to ancient hot springs.", "It got stuck in soft sand in 2009 and fell silent in 2010."]}, {"id": "new-horizons", "n": "New Horizons", "k": "Pluto and Kuiper Belt probe", "ag": "NASA", "yr": 2006, "z": "pluto", "facts": ["New Horizons flew past Pluto on 14 July 2015, giving us our first close look.", "It then flew past the Kuiper Belt object Arrokoth on 1 January 2019.", "It carries some of the ashes of Clyde Tombaugh, who discovered Pluto."]}, {"id": "orion-capsule", "n": "Orion Capsule", "k": "Crew capsule (Artemis)", "ag": "NASA", "yr": 2022, "z": "moonorb", "facts": ["Orion is NASA’s crew capsule for the Artemis Moon missions.", "On Artemis I (November–December 2022) an uncrewed Orion flew around the Moon and back.", "Its heat shield faces about 2,800 °C when it comes home."]}, {"id": "sofia", "n": "SOFIA", "k": "Flying observatory (retired)", "ag": "NASA & DLR", "yr": 2010, "z": "air", "facts": ["SOFIA was a Boeing 747 with a 2.7 m telescope peeking out of its side.", "It flew above most of Earth’s water vapour to see infrared light.", "It found water on the sunlit surface of the Moon in 2020 and retired in 2022."]}, {"id": "sls-block-1", "n": "Space Launch System (Block 1)", "k": "Moon rocket (Artemis)", "ag": "NASA", "yr": 2022, "z": "ground", "facts": ["SLS is NASA’s super-heavy rocket for the Artemis program.", "Its first flight, Artemis I, launched on 16 November 2022.", "It stands about 98 m tall with Orion on top."]}, {"id": "dart", "n": "DART", "k": "Planetary defence test (ended)", "ag": "NASA & APL", "yr": 2021, "z": "deep", "facts": ["On 26 September 2022 DART crashed into the asteroid moonlet Dimorphos on purpose.", "The impact shortened Dimorphos’s orbit by about 32 minutes.", "It was the first test of moving an asteroid to protect Earth."]}, {"id": "landsat-9", "n": "Landsat 9", "k": "Earth-imaging satellite", "ag": "NASA & USGS", "yr": 2021, "z": "eo", "facts": ["Landsat 9 launched on 27 September 2021.", "Together with Landsat 8 it photographs the whole Earth every 8 days.", "It continues a record of Earth’s land that began in 1972."]}, {"id": "titan-sub", "n": "Titan Submarine concept", "k": "Future sea explorer concept", "ag": "NASA (NIAC)", "yr": null, "z": "titan", "facts": ["This NASA concept is a submarine to explore Kraken Mare, a sea of liquid methane on Titan.", "It would study the sea’s chemistry, tides and seabed.", "It was studied by NASA’s Innovative Advanced Concepts program."]}, {"id": "m2020-wheel", "n": "Perseverance wheel", "k": "Rover part", "ag": "NASA", "yr": 2020, "z": "item-mars", "facts": ["Perseverance’s aluminium wheels are about 52 cm across.", "They have curved treads called grousers that grip the sand.", "The wheels were made thicker after Curiosity’s wheels got dented by sharp rocks."]}, {"id": "m2020-tube", "n": "Mars sample tube", "k": "Rock sample container", "ag": "NASA", "yr": 2020, "z": "item-mars", "facts": ["Perseverance seals Mars rock cores inside tubes like this one.", "Some tubes were left on the ground as a “sample depot”.", "They are meant to be brought to Earth one day for study."]}, {"id": "mppmt", "n": "Multi-Purpose Precision Maintenance Tool", "k": "Spacewalk tool", "ag": "NASA", "yr": null, "z": "item", "facts": ["A small hand tool designed for precise maintenance work in space.", "Tools for space are shaped to work with thick spacesuit gloves."]}, {"id": "nasa-insignia", "n": "NASA Insignia (“meatball”)", "k": "Emblem", "ag": "NASA", "yr": 1959, "z": "badge", "facts": ["NASA’s round blue logo is nicknamed the “meatball”.", "It shows a planet, stars, an orbiting spacecraft and a red wing-shaped vector.", "It was designed in 1959."]}, {"id": "hubble-medallion", "n": "Hubble 25th Anniversary Medallion", "k": "Commemorative medallion", "ag": "NASA", "yr": 2015, "z": "badge", "facts": ["This medallion celebrates 25 years of Hubble in 2015.", "By then Hubble had made more than a million observations."]}, {"id": "viking-emblem", "n": "Viking 40th Anniversary Emblem", "k": "Commemorative emblem", "ag": "NASA", "yr": 2016, "z": "badge", "facts": ["This emblem marks 40 years since Viking 1 landed on Mars in 1976.", "The Viking landers were the first US spacecraft to work on the Martian surface."]}, {"id": "europa-orbiter", "n": "Europa orbiter concept", "k": "Europa mission concept", "ag": "NASA", "yr": null, "z": "europa", "facts": ["This is a concept model of a spacecraft to study Jupiter’s moon Europa.", "NASA’s Europa Clipper, launched in October 2024, carries on that goal.", "Europa may hide a global ocean under its ice."]}, {"id": "explorer-1", "n": "Explorer 1", "k": "First US satellite (historic)", "ag": "US Army & JPL", "yr": 1958, "z": "eo", "facts": ["Explorer 1 was the first American satellite, launched on 31 January 1958.", "Its Geiger counter discovered the Van Allen radiation belts.", "It re-entered Earth’s atmosphere in 1970."]}, {"id": "isee-3", "n": "ISEE-3 / ICE", "k": "Sun–Earth explorer (historic)", "ag": "NASA & ESA", "yr": 1978, "z": "l1", "facts": ["ISEE-3 was the first spacecraft to orbit the L1 point between Earth and the Sun.", "Renamed ICE, it became the first spacecraft to fly through a comet’s tail, in 1985.", "Volunteers contacted it again in 2014, 36 years after launch."]}, {"id": "ast-eros", "n": "Asteroid 433 Eros", "k": "Near-Earth asteroid", "ag": "", "yr": null, "z": "ast", "facts": ["Eros is a peanut-shaped asteroid about 34 km long.", "NEAR Shoemaker orbited it and landed on it in 2001.", "It was the first near-Earth asteroid ever found, in 1898."]}, {"id": "ast-itokawa", "n": "Asteroid 25143 Itokawa", "k": "Near-Earth asteroid", "ag": "", "yr": null, "z": "ast", "facts": ["Itokawa is a rubble-pile asteroid about 535 m long.", "Japan’s Hayabusa brought grains from it back to Earth in 2010.", "It was the first asteroid sample ever returned."]}, {"id": "ast-geographos", "n": "Asteroid 1620 Geographos", "k": "Near-Earth asteroid", "ag": "", "yr": null, "z": "ast", "facts": ["Geographos is one of the most stretched-out asteroids known, about 5 km long.", "Its shape was mapped with radar from Earth."]}, {"id": "ast-toutatis", "n": "Asteroid 4179 Toutatis", "k": "Near-Earth asteroid", "ag": "", "yr": null, "z": "ast", "facts": ["Toutatis is a lumpy asteroid about 4.5 km long that tumbles as it spins.", "China’s Chang’e 2 flew past it in 2012."]}, {"id": "ast-kleopatra", "n": "Asteroid 216 Kleopatra", "k": "Main-belt asteroid", "ag": "", "yr": null, "z": "ast", "facts": ["Kleopatra is shaped like a dog bone, about 270 km long.", "It has two small moons."]}, {"id": "ast-mithra", "n": "Asteroid 4486 Mithra", "k": "Near-Earth asteroid", "ag": "", "yr": null, "z": "ast", "facts": ["Mithra looks like two lumps stuck together.", "Its shape was mapped by radar as it passed Earth in 2000."]}, {"id": "ast-golevka", "n": "Asteroid 6489 Golevka", "k": "Near-Earth asteroid", "ag": "", "yr": null, "z": "ast", "facts": ["Golevka is a small asteroid about 500 m across.", "Scientists measured sunlight slowly nudging its orbit, called the Yarkovsky effect."]}, {"id": "ast-1996hw1", "n": "Asteroid 8567 1996 HW1", "k": "Near-Earth asteroid", "ag": "", "yr": null, "z": "ast", "facts": ["1996 HW1 is a contact binary: two pieces resting against each other.", "It is about 3.8 km long."]}, {"id": "neb-crab", "n": "Crab Nebula", "k": "Supernova remnant (deep sky)", "ag": "", "yr": null, "z": "sky", "facts": ["The Crab Nebula is what is left of a star that exploded in the year 1054.", "Astronomers in China recorded the explosion; it was visible in daylight for weeks.", "A spinning neutron star at its centre turns 30 times a second."]}, {"id": "neb-pillars", "n": "Pillars of Creation", "k": "Star-forming clouds (deep sky)", "ag": "", "yr": null, "z": "sky", "facts": ["The Pillars of Creation are towers of gas and dust in the Eagle Nebula, about 6,500 light-years away.", "New stars are being born inside them.", "Hubble made them famous in 1995, and Webb photographed them again in 2022."]}, {"id": "neb-etacar", "n": "Eta Carinae (Homunculus Nebula)", "k": "Giant star system (deep sky)", "ag": "", "yr": null, "z": "sky", "facts": ["Eta Carinae is a pair of huge stars about 7,500 light-years away.", "In the 1840s it erupted and became one of the brightest stars in the sky.", "That outburst made the hourglass-shaped Homunculus Nebula."]}, {"id": "neb-dgtau", "n": "DG Tau", "k": "Young star (deep sky)", "ag": "", "yr": null, "z": "sky", "facts": ["DG Tau is a very young star still surrounded by a disk of gas and dust.", "It shoots out jets of material from its poles."]}, {"id": "snr-sn1006", "n": "SN 1006", "k": "Supernova remnant (deep sky)", "ag": "", "yr": null, "z": "sky", "facts": ["SN 1006 was the brightest supernova ever recorded, seen in the year 1006.", "It was bright enough to read by at night."]}, {"id": "snr-sn1987a", "n": "SN 1987A", "k": "Supernova remnant (deep sky)", "ag": "", "yr": null, "z": "sky", "facts": ["SN 1987A exploded in the Large Magellanic Cloud, and its light reached Earth in 1987.", "It was the closest supernova seen in nearly 400 years.", "Webb found signs of a neutron star at its centre."]}, {"id": "snr-tycho", "n": "Tycho’s Supernova Remnant", "k": "Supernova remnant (deep sky)", "ag": "", "yr": null, "z": "sky", "facts": ["Tycho Brahe watched this supernova in 1572.", "It helped show that the sky beyond the planets can change."]}, {"id": "star-uscorpii", "n": "U Scorpii", "k": "Recurrent nova (deep sky)", "ag": "", "yr": null, "z": "sky", "facts": ["U Scorpii is a white dwarf star that flares up as a nova every 10 years or so.", "It steals gas from a companion star until it explodes on its surface."]}, {"id": "storm-katrina", "n": "Hurricane Katrina (3D model)", "k": "Hurricane data model", "ag": "NASA", "yr": 2005, "z": "storm", "facts": ["This 3D model shows Hurricane Katrina’s rain, measured from space.", "Katrina hit the US Gulf Coast in August 2005.", "NASA’s TRMM satellite measured the rain inside it."]}, {"id": "storm-sandy", "n": "Hurricane Sandy (3D model)", "k": "Hurricane data model", "ag": "NASA", "yr": 2012, "z": "storm", "facts": ["This 3D model shows Hurricane Sandy, which struck the US East Coast in October 2012.", "Satellites tracked it as one of the largest Atlantic hurricanes ever measured."]}, {"id": "storm-julio", "n": "Hurricane Julio (3D model)", "k": "Hurricane data model", "ag": "NASA", "yr": 2014, "z": "storm", "facts": ["This 3D model shows Hurricane Julio in the Pacific in August 2014.", "NASA’s GPM satellite measured the rain falling inside it."]}, {"id": "terra", "n": "Terra", "k": "Earth-observing satellite", "ag": "NASA, Japan & Canada", "yr": 1999, "z": "eo", "facts": ["Terra launched on 18 December 1999 and is NASA’s flagship Earth-watching satellite.", "Its five instruments study land, oceans, clouds and air pollution together.", "Its MODIS camera images the whole Earth every one to two days."]}];
